/**
 * Every photo is declared here: the words are hand-written, the files and their
 * sizes are generated by `npm run photos` (scripts/photos.mjs).
 *
 * To add a photo:
 *   1. Put the original in photos/originals/ (not committed to git).
 *   2. Add an entry below. The slug becomes the file name Google sees, so make it descriptive:
 *      what's in the picture and where, e.g. "anish-seth-howrah-bridge-dawn".
 *   3. Run `npm run photos`, then commit the new files in public/photos and the generated JSON.
 *
 * Only plain data and types here: the build script imports this file straight into Node.
 */

export type Photo = {
  /** Unique, lowercase, hyphenated. Also the file name. */
  slug: string;
  /** Path of the original, from the project root. */
  source: string;
  title: string;
  /** What the picture shows, for someone who can't see it. One sentence, no keyword lists. */
  alt: string;
  /** Visible under the photo; this is the text search engines read next to it. */
  caption: string;
  /** Set when the picture is of Anish Seth, which ties it to the same person in structured data. */
  portrait?: boolean;
  /** The background is transparent, so nothing may be drawn behind the image. */
  cutout?: boolean;
  /** Who took it, when that isn't Anish Seth. Changes the creator and credit line. */
  photographer?: string;
  /** Only where it's known, e.g. "Kolkata, India". Never guessed. */
  location?: string;
  /** YYYY-MM-DD, only where it's known. */
  taken?: string;
};

export type PhotoSeries = {
  slug: string;
  title: string;
  /** Short line for cards and meta descriptions (50–160 characters). */
  summary: string;
  /** A few honest sentences shown at the top of the series page. */
  story: string[];
  /** YYYY-MM-DD this series last changed; feeds the sitemap. */
  updated: string;
  /** The first photo is the cover. */
  photos: Photo[];
};

